import type { AdminComment, CommentModerationAction, CommentStatus } from '../../../core/ports/comments.js';
import type { CommentsTranslator } from '../../messages.en.js';
import type { RowActionState } from '../../rules.js';
import { DataTable } from '../../../react/components/DataTable.js';
import { RowMenu } from '../../../react/components/RowMenu/RowMenu.js';
import { ConfirmDialog } from '../../../react/components/ConfirmDialog/ConfirmDialog.js';
import { agentHandle } from '@jini-ai/agentic';
import { interpolate } from '@jini-ai/ui/panel-kit';
import { useWiredCommentQueue } from '../hooks/use-comment-queue.hooks.js';
import { useQueueSection, useQueueActionsCell, useQueueTable, useQueueToolbar } from '../hooks/QueueSection.hooks.js';

const STATUS_OPTIONS: readonly CommentStatus[] = ["pending", "approved", "spam", "trash"];

/** The status-filter `<select>` — pure presentation, no state of its own. */
function QueueToolbar({
  status,
  onStatusChange,
  t,
}: {
  status: CommentStatus;
  onStatusChange: (s: CommentStatus) => void;
  t: CommentsTranslator;
}) {
  const { onChange } = useQueueToolbar({ onStatusChange });
  return (
    <div className="toolbar">
      <div className="field">
        <label className="field-label" htmlFor="comments-status-filter">
          {t("Status")}
        </label>
        <select
          id="comments-status-filter"
          value={status}
          onChange={onChange}
          {...agentHandle({ handle: "comments-status-filter" }, { role: "field", label: "Filter the moderation queue by status" })}
        >
          {STATUS_OPTIONS.map((s) => (
            <option key={s} value={s}>
              {t(s)}
            </option>
          ))}
        </select>
      </div>
    </div>
  );
}

/** The moderation-queue table's "More" column — a `RowMenu` built from `commentRowMenuItems`, or
 *  an em dash when the operator's permissions leave no items, plus this row's own error (if the
 *  last action against it failed). Top-level rather than an inline `cell` closure so it has its
 *  own directly-testable scope, per `commentRowMenuItems`'s own risk ranking. */
export function QueueActionsCell(props: {
  comment: AdminComment;
  agentHandleBase: string;
  permissions: readonly string[];
  status: CommentStatus;
  rowState: RowActionState;
  t: CommentsTranslator;
  onModerate: (comment: AdminComment, action: CommentModerationAction) => void;
  onRequestPurge: (comment: AdminComment) => void;
}) {
  const { menuItems } = useQueueActionsCell(props);
  return (
    <>
      {menuItems.length > 0 ? (
        <RowMenu
          triggerLabel={interpolate({ template: props.t('Actions for the comment by "{author}"'), vars: {
            author: props.comment.authorName,
          } })}
          agentHandle={`${props.agentHandleBase}-menu`}
          items={menuItems}
        />
      ) : (
        <span className="muted-cell">—</span>
      )}
      {props.rowState.error ? (
        <div className="notice error" role="alert">
          {props.rowState.error}
        </div>
      ) : null}
    </>
  );
}

/** The populated-queue view: the table plus its "Load more" pager. Only rendered once
 *  `QueueItemsView` has already ruled out the loading/empty states. */
function QueueTable(props: {
  items: readonly AdminComment[];
  nextCursor: string | null;
  loadingMore: boolean;
  loadMore: () => void;
  permissions: readonly string[];
  status: CommentStatus;
  stateFor: (id: string) => RowActionState;
  t: CommentsTranslator;
  onModerate: (comment: AdminComment, action: CommentModerationAction) => void;
  onRequestPurge: (comment: AdminComment) => void;
}) {
  const { columns } = useQueueTable(props);
  return (
    <>
      <DataTable
        rows={props.items}
        rowKey={(comment) => comment.id}
        columns={columns}
      />
      {props.nextCursor ? (
        <button
          type="button"
          className="btn-secondary"
          onClick={props.loadMore}
          disabled={props.loadingMore}
          {...agentHandle({ handle: "comments-load-more" }, { role: "button", label: "Load more comments" })}
        >
          {props.loadingMore ? props.t("Loading…") : props.t("Load more")}
        </button>
      ) : null}
    </>
  );
}

/** Dispatches between the three queue-body states (loading / empty / populated) as a flat
 *  if-chain instead of a nested ternary — the nesting was the cognitive-complexity cost in the
 *  original inline JSX, not the branch count itself. */
function QueueItemsView(props: {
  items: readonly AdminComment[] | null;
  status: CommentStatus;
  nextCursor: string | null;
  loadingMore: boolean;
  loadMore: () => void;
  permissions: readonly string[];
  stateFor: (id: string) => RowActionState;
  t: CommentsTranslator;
  onModerate: (comment: AdminComment, action: CommentModerationAction) => void;
  onRequestPurge: (comment: AdminComment) => void;
}) {
  if (!props.items) return <div className="notice">{props.t("Loading comments…")}</div>;
  if (props.items.length === 0) {
    return (
      <div className="card">
        <div className="empty-state">
          <p>{interpolate({ template: props.t("No {status} comments."), vars: { status: props.status } })}</p>
        </div>
      </div>
    );
  }
  return <QueueTable {...props} items={props.items} />;
}

/** The Purge confirm dialog. Stays mounted unconditionally (driven by `open`) — see
 *  `useCommentQueue`'s `pendingPurge` doc comment for why. */
function QueuePurgeDialog(props: {
  pendingPurge: AdminComment | null;
  busy: boolean;
  t: CommentsTranslator;
  onConfirm: () => void;
  onCancel: () => void;
}) {
  return (
    <ConfirmDialog
      open={props.pendingPurge !== null}
      agentHandle="comments-purge"
      title={props.t("Permanently delete this comment?")}
      body={
        props.pendingPurge ? (
          <p>
            {interpolate({ template: props.t('Permanently delete this comment by "{author}"? This cannot be undone.'), vars: {
              author: props.pendingPurge.authorName,
            } })}
          </p>
        ) : null
      }
      confirmLabel={props.t("Permanently delete")}
      destructive
      pending={props.busy}
      onConfirm={props.onConfirm}
      onCancel={props.onCancel}
    />
  );
}

export interface QueueSectionProps {
  permissions: readonly string[];
  t?: CommentsTranslator;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. Defaulted to the real hook, so production callers (the exported
   *  `Comments` below) pass nothing and behave exactly as before. */
  useCommentQueueHook?: typeof useWiredCommentQueue;
}

/** Exported (2026-08-14, previously module-private) so `QueueSection.unit.test.tsx` can drive its
 *  own DI seam directly — the same reason `AiAssistant.tsx`'s `AdminExecutionMode` is exported. */
export function QueueSection(props: QueueSectionProps) {
  const {
    t,
    status,
    setStatus,
    items,
    nextCursor,
    error,
    loadingMore,
    loadMore,
    stateFor,
    onModerate,
    pendingPurge,
    setPendingPurge,
    onPurge,
    onCancelPurge,
    purgeBusy,
  } = useQueueSection(props);

  if (error && !items) return <div className="notice error">{error}</div>;

  return (
    <div>
      <QueueToolbar status={status} onStatusChange={setStatus} t={t} />

      {error ? <div className="notice error">{error}</div> : null}

      <QueueItemsView
        items={items}
        status={status}
        nextCursor={nextCursor}
        loadingMore={loadingMore}
        loadMore={loadMore}
        permissions={props.permissions}
        stateFor={stateFor}
        t={t}
        onModerate={onModerate}
        onRequestPurge={setPendingPurge}
      />

      <QueuePurgeDialog
        pendingPurge={pendingPurge}
        busy={purgeBusy}
        t={t}
        onConfirm={onPurge}
        onCancel={onCancelPurge}
      />
    </div>
  );
}

import { createContext, createElement, useContext, useCallback, useEffect, useMemo, useRef, type Dispatch, type SetStateAction, type ReactNode } from 'react';
import { useCachedLoader, useFetchQuery, useInvalidate, useFetchQueryScope } from '@jini-ai/ui/fetch-query';
import { AdminConfigError } from '../../../core/module/create-admin.js';
import { useController } from '../../../core/react/use-controller.js';
import type { AdminComment, AdminCommentsPort, AdminCommentsQueuePage, CommentModerationAction, CommentStatus } from '../../../core/ports/comments.js';
import type { CommentQueueState } from '../../models.js';
import { createCommentQueueController } from '../../controllers/comment-queue.controller.js';
import { KEYS, emptyRowState, type RowActionState } from '../../rules.js';
import type { CommentsEventsPort } from '../../ports.js';
import { englishComments, type CommentsTranslator } from '../../messages.en.js';
import { useCommentsPorts, useCommentsTranslation } from './CommentsPorts.hooks.js';

const NO_GRANTS: readonly string[] = [];
/** What renders before the controller's first snapshot; mirrors the controller's initial state. */
const BEFORE_FIRST_SNAPSHOT: CommentQueueState = Object.freeze({
  status: 'pending', items: null, nextCursor: null, error: null, loadingMore: false, rowState: {}, pendingPurge: null,
});
type QueueStore = ReturnType<typeof createCommentQueueController>;
type QueuePageLoader = (required: { status: CommentStatus; cursor: string }) => Promise<AdminCommentsQueuePage>;

/** Host-owned identity; never infer tenancy or the current operator from returned rows. */
export interface CommentQueueScope {
  readonly workspaceId: string;
  readonly principalId: string;
}
const CommentQueueScopeContext = createContext<CommentQueueScope | null>(null);

/** Supply live workspace/principal identity to wired queues, including with a singleton API.
 * Update scope at the authentication boundary before rendering the next principal's children.
 */
export function CommentQueueScopeProvider({ scope, children }: { scope: CommentQueueScope; children: ReactNode }) {
  return createElement(CommentQueueScopeContext.Provider, { value: scope }, children);
}

export interface CommentQueueController {
  status: CommentStatus;
  setStatus: Dispatch<SetStateAction<CommentStatus>>;
  items: readonly AdminComment[] | null;
  nextCursor: string | null;
  error: string | null;
  loadingMore: boolean;
  loadMore: () => void;
  stateFor: (id: string) => RowActionState;
  onModerate: (comment: AdminComment, action: CommentModerationAction) => Promise<void>;
  pendingPurge: AdminComment | null;
  setPendingPurge: Dispatch<SetStateAction<AdminComment | null>>;
  onPurge: () => Promise<void>;
}
type QueueDisplay = Pick<CommentQueueController, 'status' | 'items' | 'nextCursor' | 'error' | 'loadingMore' | 'pendingPurge'>;
type QueueActions = Omit<CommentQueueController, keyof QueueDisplay>;

/** Preserve the hook's loading defaults while no controller from the current scope is attached. */
function queueDisplay({ snapshot }: { snapshot: CommentQueueState | null }, _optional: Record<string, never> = {}): QueueDisplay {
  const { status, items, nextCursor, error, loadingMore, pendingPurge } = snapshot ?? BEFORE_FIRST_SNAPSHOT;
  return { status, items, nextCursor, error, loadingMore, pendingPurge };
}

/** Resolve React's value/updater forms against the attached controller's current snapshot. */
function resolveSetState<T>({ value, current }: { value: SetStateAction<T>; current: T }, _optional: Record<string, never> = {}): T {
  return typeof value === 'function' ? (value as (previous: T) => T)(current) : value;
}
/** Adapt public React setters/actions to the attached headless controller.
 * Before the controller exists every gesture is inert and every row reads as idle.
 */
function bindQueueActions(
  { controller }: { controller: QueueStore | null },
  _optional: Record<string, never> = {},
): QueueActions {
  return {
    setStatus: value => { if (controller) controller.setStatus({ status: resolveSetState({ value, current: controller.getSnapshot().status }) }); },
    loadMore: () => controller?.loadMore({}),
    stateFor: id => controller?.stateFor({ id }) ?? emptyRowState(),
    onModerate: async (comment, action) => { await controller?.onModerate({ comment, action }); },
    setPendingPurge: value => { if (controller) controller.setPendingPurge({ comment: resolveSetState({ value, current: controller.getSnapshot().pendingPurge }) }); },
    onPurge: async () => { await controller?.onPurge({}); },
  };
}
/** Cursor pages share page one's scoped cache prefix, so invalidation stays within that scope. */
function useCursorPageLoader(
  { api, queueRoot, status, cursor }: { api: AdminCommentsPort; queueRoot: readonly (string | number)[]; status: CommentStatus; cursor: string },
  _optional: Record<string, never> = {},
): QueuePageLoader {
  const cursorKey = useMemo(() => [...queueRoot, status, 'cursor', cursor], [queueRoot, status, cursor]);
  const fetchCursor = useCallback(() => api.listCommentsQueue({}, { status, cursor }), [api, status, cursor]);
  const cursorLoader = useCachedLoader({ key: cursorKey, fetch: fetchCursor }, { staleTime: 0 });
  return ({ status: requestedStatus, cursor: requestedCursor }) => cursorLoader.load({
    key: [...queueRoot, requestedStatus, 'cursor', requestedCursor],
    fetch: () => api.listCommentsQueue({}, { status: requestedStatus, cursor: requestedCursor }),
  });
}
/** Effects attach to injected ports; cursor/row state belongs to the headless controller.
 * The shared cache guards stale page-one keys. Cursor settlement is guarded separately because
 * one fixed query key cannot represent an accumulated list of appended pages.
 * All read/invalidation keys include explicit workspace/principal identity and API identity.
 * A scope change hides the previous controller immediately, before effect cleanup runs.
 */
export function useCommentQueue(
  { api, scope, permissions = NO_GRANTS }: { api: AdminCommentsPort; scope: CommentQueueScope; permissions?: readonly string[] },
  { t = englishComments, events }: { t?: CommentsTranslator; events?: CommentsEventsPort } = {},
): CommentQueueController {
  const invalidate = useInvalidate();
  // Weak API keys preserve sharing between consumers without retaining APIs from previous sessions.
  // Explicit workspace/principal keys below also isolate hosts that retain one API across sessions.
  const apiScope = useFetchQueryScope({ owner: api });
  const queueRoot = useMemo(() => [...KEYS.queueRoot, apiScope, scope.workspaceId, scope.principalId], [apiScope, scope.workspaceId, scope.principalId]);
  const invalidateQueue = useCallback(() => invalidate({ key: queueRoot }), [invalidate, queueRoot]);
  const loadPageRef = useRef<QueuePageLoader | null>(null);
  const { controller: attachedController, snapshot: attachedSnapshot } = useController({
    create: () => ({ ...createCommentQueueController({ api, permissions }, { t, onInvalidate: invalidateQueue, loadPage: required => loadPageRef.current!(required) }), queueRoot }),
    dependencies: [api, invalidateQueue],
  });
  // Effects replace the controller after commit; hide the previous scope during that render too.
  const controller = attachedController?.queueRoot === queueRoot ? attachedController : null;
  const snapshot = controller ? attachedSnapshot : null;
  useEffect(() => { controller?.configure({ permissions, t }); }, [controller, permissions, t]);
  const display = queueDisplay({ snapshot });
  const { status } = display;
  // The gesture remains controller-owned, including its same-tick lock and generation fence.
  // Only I/O changes: cursor pages now share page one's provider and status invalidation prefix.
  loadPageRef.current = useCursorPageLoader({ api, queueRoot, status, cursor: display.nextCursor ?? '' });
  const firstPage = useFetchQuery({ key: [...queueRoot, status], fetch: () => api.listCommentsQueue({}, { status }) });
  useEffect(() => { controller?.settleFirstPage({ page: firstPage.data ?? null, error: firstPage.error, status }); }, [controller, firstPage.data, firstPage.error, status]);
  // Stable identity avoids resubscribing on every render. The host filters out unrelated
  // resources. Unmount removes the subscription even if another cache observer remains active.
  useEffect(() => events?.subscribe({ onRefresh: invalidateQueue }), [events, invalidateQueue]);
  return { ...display, ...bindQueueActions({ controller }) };
}
export function useWiredCommentQueue(
  { permissions }: { permissions: readonly string[] },
  _optional: Record<string, never> = {},
): CommentQueueController {
  const { commentsApi, commentsEvents } = useCommentsPorts();
  const t = useCommentsTranslation();
  const scope = useContext(CommentQueueScopeContext);
  if (!scope) throw new AdminConfigError({ issues: ['Comment queue requires an explicit workspace/principal scope'] });
  return useCommentQueue({ api: commentsApi, scope, permissions }, { t, ...(commentsEvents ? { events: commentsEvents } : {}) });
}

import { useEffect, useState, useSyncExternalStore, useCallback } from 'react';
import type { DependencyList } from 'react';
import type { ControllerStore } from '../module/controller-store.js';
/** Factory runs after commit, never during render. Each effect attachment owns a fresh
 * controller, so StrictMode's cleanup/replay cannot revive a disposed controller. */
export function useController<C extends ControllerStore<unknown>>(
  { create, dependencies }: { create: () => C; dependencies: DependencyList },
  {
    start,
  }: { start?: (required: { controller: C }, optional?: Record<string, never>) => void } = {},
) {
  const [controller, setController] = useState<C | null>(null);
  useEffect(() => {
    const current = create();
    setController(current);
    start?.({ controller: current });
    return () => current.dispose();
    // Dependencies are explicitly supplied by the owning hook, like useMemo's contract.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, dependencies);
  const subscribe = useCallback(
    (listener: () => void) => controller?.subscribe({ listener }) ?? (() => {}),
    [controller],
  );
  const snapshot = useSyncExternalStore(
    subscribe,
    () => (controller?.getSnapshot() ?? null) as ReturnType<C['getSnapshot']> | null,
    () => null,
  );
  return { controller, snapshot };
}

import { ConfirmDialog } from '../../../react/components/ConfirmDialog/ConfirmDialog.js';
import { agentHandle } from '@jini-ai/agentic';
import { useWiredFormSubmissionDetail } from '../hooks/use-form-submission-detail.hooks.js';
import { useFormSubmissionDate } from '../hooks/use-form-submission-date.hooks.js';
import { FormSubmissionDate } from "./FormSubmissionDate.js";
import { formSubmissionRows, type FormAnswerColumn } from '../../html-rules.js';
export interface FormSubmissionDetailProps {
  formId: string;
  submissionId: string;
  onBack: () => void;
  onDeleted: () => void;
  /** Dependency injection seam for tests — see `PostsProps.usePostsHook` for the convention. */
  useFormSubmissionDetailHook?: typeof useWiredFormSubmissionDetail;
  /** Translator closure — see `FormEditor()`'s own `t`. */
  t: (key: string) => string;
  answerColumns?: readonly FormAnswerColumn[];
}

export function FormSubmissionDetail({
  formId,
  submissionId,
  onBack,
  onDeleted,
  useFormSubmissionDetailHook = useWiredFormSubmissionDetail,
  t,
  answerColumns = [],
}: FormSubmissionDetailProps, _optional: Record<string, never> = {}) {
  const formatDate = useFormSubmissionDate({});
  const { submission, error, confirmOpen, deleting, requestDelete, cancelDelete, confirmDelete, fileUrl } = useFormSubmissionDetailHook({
    formId,
    submissionId,
    onDeleted,
  });

  if (error && !submission) return <div className="notice error">{error}</div>;
  if (!submission) return <div className="notice">{t("Loading submission…")}</div>;

  return (
    // `form-submission-detail` (`styles/forms.css`) — the back button, table, and Delete button
    // were flush siblings with no gap between them (owner: "pad the buttons"), so the back
    // button sat right on top of the table and Delete sat right underneath it. Same
    // flex-column-plus-gap idiom `.field-group` already uses elsewhere for vertical rhythm,
    // rather than one-off margins on each button.
    <div className="form-submission-detail">
      <button
        type="button"
        className="btn-secondary"
        onClick={onBack}
        aria-label={t("Back to submissions")}
        {...agentHandle({ handle: "form-submission-back" }, { role: "link", label: "Back to this form's list of submissions" })}
      >
        &larr; {t("Back")}
      </button>
      <SubmissionStatusNotices submission={submission} error={error} t={t} />
      <div className="table-scroll">
        <table className="list-table">
          <tbody>
            <tr>
              <th>{t("Submitted at")}</th>
              <td><FormSubmissionDate date={formatDate({ iso: submission.submittedAt })} /></td>
            </tr>
            <tr>
              <th>{t("Source IP")}</th>
              <td>{submission.sourceIp}</td>
            </tr>
            {formSubmissionRows({ data: submission.data, answerColumns, evidence: submission.evidence }, { unknownFieldLabel: t("Unknown field") }).map(({ key, label, value, file }) => {
              const href = file ? fileUrl(file) : null;
              return (
                <tr key={key}>
                  <th className="jini-submission-field-label">{label}</th>
                  <td>{href && file ? <a href={href} download={file.filename} {...agentHandle({ handle: `form-submission-file-${key}` }, { role: "link", label: `Download the uploaded file ${file.filename}` })}>{value}</a> : value}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      <button
        type="button"
        className="btn-danger"
        disabled={deleting}
        onClick={requestDelete}
        {...agentHandle({ handle: "form-submission-delete" }, {
          role: "button",
          label: "Move this submission to the trash. Opens a confirmation dialog first.",
        })}
      >
        {t("Delete submission")}
      </button>
      <ConfirmDialog
        open={confirmOpen}
        agentHandle="form-submission-delete-confirm"
        title={t("Move to trash?")}
        body={<p>{t("It will disappear from this list. You can restore it from the Trash.")}</p>}
        confirmLabel={t("Move to trash")}
        destructive
        pending={deleting}
        onConfirm={confirmDelete}
        onCancel={cancelDelete}
      />
    </div>
  );
}

/** Historical context is displayed as plain text; authored HTML is never executed here. */
function SubmissionEvidenceNotice({ submission, t }: {
  submission: import('../../models.js').AdminFormSubmission; t: (key: string) => string;
}) {
  return !submission.evidence ? <div className="notice">{t("original schema/consent unavailable")}{!submission.validation ? <p>{t("validation unknown")}</p> : null}</div> : <div className="notice">
        <p>{t("Schema hash")}: <code>{submission.evidence.schemaHash}</code></p>
        {submission.evidence.consent.map(consent => <p key={consent.fieldId}>{consent.wording}{consent.helpText ? ` — ${consent.helpText}` : ""}</p>)}
      </div>;
}

function SubmissionStatusNotices({ submission, error, t }: {
  submission: import('../../models.js').AdminFormSubmission; error: string | null; t: (key: string) => string;
}) {
  return <>
      {error ? <div className="notice error">{error}</div> : null}
      {submission.notificationDelivery && submission.notificationDelivery.failed > 0 ? <div className="notice error" role="alert">
        {t("Email notification failed. The submission is saved here. Check the email provider settings before sending a new notification.")}
        <p>{t("Details: FORM_NOTIFICATION_FAILED")} ({submission.notificationDelivery.failed})</p>
      </div> : null}
      <SubmissionEvidenceNotice submission={submission} t={t} />
      {submission.validation?.status === "invalid" ? <div className="notice error" role="alert">
        <p>{t("Imported for review: this submission did not pass the form checks.")}</p>
        <ul>{submission.validation.fieldErrors.map(({ field, reason }, index) => <li key={`${field}-${index}`}>{field}: {reason}</li>)}</ul>
      </div> : null}
  </>;
}

import type { FormProviderDescription } from "@jini-ai/cms/forms";
import type { AdminFormProviderSelection, AdminFormsPort } from "../../../core/ports/forms.js";
import { formView } from "../../models.js";
import { describeApiError } from "../../../core/transport/errors.js";
import { useFormsPorts, useFormsOptions } from "./FormsPorts.hooks.js";
import { useController } from "../../../core/react/use-controller.js";
import { createFormEditorController, initialFormEditorState, type FormEditorState } from "../../controllers/form-editor.controller.js";
import { formHtmlEmbed, formAnswerColumns, type FormAnswerColumn } from "../../html-rules.js";
import { useEffect, useRef, useState } from "react";
import { useDirtyGuard } from "@jini-ai/ui/panel-kit";
import { formEditorBaseline, formEditorDraft } from "../../form-editor-dirty.js";
import type { AdminFormDefinition, AdminFormField, AdminFormNotify } from "../../models.js";
import { useFetchMutation, useFetchQuery } from "@jini-ai/ui/fetch-query";
import { FORM_TABS, KEYS, existingFieldIdsOf, nextTabIndex, visibleFormEditorError } from "../../rules.js";

/**
 * @file Everything the FormEditor SCREEN does — load, save, status toggle, and the Fields/
 * Submissions tab strip's roving-tabindex focus management — so `FormEditor`'s exported component
 * in `FormEditor.tsx` is only markup.
 *
 * Moved from the host — same load effect, same save/status-toggle error strings, same "later failure
 * keeps the editor on screen" guard (the audit-blocker fix this screen's file header describes —
 * see `FormEditor.tsx`'s own header for the full rationale, which stays with the guard in the view
 * since it describes render behaviour, not this hook's state).
 *
 * `tab` (ADR-063, 2026-08-31): no longer local state — it is `props.tab`, derived from the route
 * (`/forms/:formId` vs `/forms/:formId/submissions`) by `panels.tsx`/`FormEditor.tsx`. Switching
 * tabs calls the injected `navigate` (real app router), the same idiom `Deployment.tsx`'s tab strip
 * uses, rather than a local `setTab` — Submissions has its own independent fetch, so a tab switch
 * is a genuine route change, not a display-layer filter over data already in hand.
 *
 * `tabRefs` moves here too, per Pattern 1 (every `useRef` moves with state/effects, not just
 * `useState`) — the view still attaches each button via its own `ref` callback (an unavoidably
 * DOM-side operation), but the ref array itself and the keydown-to-focus-change logic
 * (`onTabsKeyDown`) are behaviour, not markup.
 *
 * Naming follows `hooks/use-settings-slice.hooks.ts`: `use-<thing>.hooks.ts`. Feature-local because
 * nothing outside `features/forms` needs it.
 *
 * `port`/`navigate` are injected — see `core/ports/forms.ts` (shared with `use-forms-list.hooks.ts`,
 * since both read/write the same `AdminFormDefinition` resource) — rather than reaching `lib/api`/
 * `lib/router` directly, so a test can describe load/save outcomes against `the memory adapter`
 * instead of stubbing global `fetch`. `useWiredFormEditor` below is the zero-argument pair
 * `FormEditor.tsx` actually mounts.
 *
 * `t` (standing i18n rule — a component with a hook gets a BOUND `t` from that hook, not its own
 * `useAdminLocale()`/dictionary import, same shape `use-post-editor.hooks.ts` established for this
 * conversion): injected alongside `port`/`navigate` because `FormEditor.tsx` itself (the copy
 * around this hook's own state — tab labels, Save button, etc.) DOES need translated strings, even
 * though this hook's own error messages don't. Pre-bound to `(key: string) => string`.
 * `useAdminLocale()` and `FORMS_DICT` are called/read only inside {@link useWiredFormEditor}.
 *
 * `@jini-ai/ui/fetch-query` migration (2026-08-12): the load is one `useFetchQuery` keyed on
 * `KEYS.form(formId)` (disabled for `isNew`, matching the original `if (isNew) return;` early-out).
 * `form`/`name`/`slug`/`fields`/`notify` live in the section controller — the operator edits `name`/`slug`/
 * `fields`; `notify` has no UI of its own (owner ask 2026-09-22 removed the notify checkbox/
 * recipients input — see this file's own `notify` state comment) and is only ever carried through
 * unchanged. All are seeded from `list.data` exactly once per `formId` via `seededFormIdRef`, the
 * same shape `collections/hooks/use-collection-entry-editor.hooks.ts`'s `seededIdentityRef`
 * establishes (see that file's header for the regression it guards against: a background refetch of
 * the SAME identity must not clobber in-progress edits). `handleSave`/`handleStatusToggle` set `form`
 * (and, for save, the rest of the seeded fields) directly from each MUTATION's own response, and
 * neither mutation invalidates this hook's OWN `KEYS.form(formId)` read (only the sibling
 * `KEYS.list`) — mirroring `save()`/`toggleLifecycle()` in that same collections hook, which
 * invalidate only the sibling `KEYS.entries(...)`, never their own `KEYS.entry(...)`, for the
 * identical reason: a response already in hand needs no redundant background refetch of itself. This
 * eliminates the load race an external audit flagged at this file's old line 117 (`useEffect(load,
 * [props.formId, port])` with no cancellation guard, so a formId change mid-flight could commit a
 * stale response): a keyed query cannot commit a response belonging to a prior key, by construction.
 */

export interface FormEditorController {
  isNew: boolean;
  /** `null` until the initial load settles (or always, for `isNew`) — the caller renders a loading
   *  state or the empty create form accordingly. */
  form: AdminFormDefinition | null;
  providers?: readonly FormProviderDescription[] | undefined;
  providersError?: string | null;
  provider: AdminFormProviderSelection;
  setProvider: (value: AdminFormProviderSelection) => void;
  name: string;
  setName: (value: string) => void;
  slug: string;
  setSlug: (value: string) => void;
  mode: "builder" | "html";
  onModeChange: (mode: "builder" | "html") => void;
  html: string;
  setHtml: (html: string) => void;
  copyEmbed: () => void;
  copyFeedback: string | null;
  answerColumns: FormAnswerColumn[];
  fields: AdminFormField[];
  setFields: (fields: AdminFormField[]) => void;
  tab: "fields" | "submissions";
  /** Navigates to this form's Fields or Submissions route — real `navigate()`, not local state
   *  (ADR-063: Submissions has its own independent fetch, so a tab switch is a genuine route
   *  change, the same idiom `Deployment.tsx`'s tab strip uses). Pushes a history entry (no
   *  `replace`) so browser back/forward move naturally between the two routes, unlike the
   *  `?tab=` screens' `replace: true` view-filter switches. */
  onTabChange: (tab: "fields" | "submissions") => void;
  error: string | null;
  saving: boolean;
  /** Already-persisted field ids on the loaded form — see `existingFieldIdsOf`. */
  existingFieldIds: string[];
  /** Tabs render only for an existing, loaded form — never for `isNew`, and never before `form`
   *  has loaded. */
  showTabs: boolean;
  /** Per-tab-button refs, indexed the same as `FORM_TABS` — attach via each button's own `ref`
   *  callback in the view. */
  tabRefs: React.MutableRefObject<Array<HTMLButtonElement | null>>;
  /** Roving-tabindex keydown handler for the tablist `<div>` — ArrowLeft/ArrowRight/Home/End move
   *  both the selected tab and DOM focus together. */
  onTabsKeyDown: (e: React.KeyboardEvent) => void;
  handleSave: () => void;
  handleStatusToggle: () => void;
  /** Back with unsaved edits opens an app confirm modal instead of discarding them silently
   *  (Chrome check, 2026-10-11). `onBack` routes through the injected navigation port;
   *  only a dirty draft requires confirmation. */
  leave: { confirmOpen: boolean; onBack: (event: { preventDefault: () => void }) => void; confirm: () => void; cancel: () => void };
  /** Bound translator — see this file's own header for why it arrives via the hook rather than
   *  `FormEditor.tsx` calling `useAdminLocale()`/`FORMS_DICT` directly. */
  t: (key: string) => string;
}

/** Ordinary Builder saves keep their existing endpoint/permissions; a mode change is explicit. */
function authoringPatch({ mode, html, savedMode }: { mode: "builder" | "html"; html: string; savedMode: "builder" | "html" | undefined }) {
  if (mode === "html") return { mode, html };
  return savedMode === "html" ? { mode } : {};
}
/** Load and save the editor through its injected port, preserving authoring and collection metadata.
 * @complexity O(f + b) draft state for fields/HTML bytes; one definition request per save, no provider I/O.
 * @overallScore 95 — Low: the existing screen lifecycle remains one hook with independently tested callbacks. */
export function useFormEditor(
  props: { formId: string; tab: "fields" | "submissions"; port: AdminFormsPort; navigate: (path: string) => void; t: (key: string) => string },
  { clipboard }: { clipboard?: { writeText: (text: string) => Promise<void> } } = {},
): FormEditorController {
  const { port, navigate, t } = props;
  const { tab } = props;
  const isNew = props.formId === "new";
  const { controller: stateController, snapshot: stateSnapshot } = useController({ create: () => createFormEditorController({}), dependencies: [] });
  const state = stateSnapshot ?? initialFormEditorState({});
  const { form, mode, html, copyFeedback, name, slug, fields, notify, provider } = state;
  const setProvider = (value: AdminFormProviderSelection) => stateController?.update({ key: "provider", value });
  const setForm = (value: FormEditorStateValue<"form">) => stateController?.update({ key: "form", value });
  const setHtml = (value: FormEditorStateValue<"html">) => stateController?.update({ key: "html", value });
  const setCopyFeedback = (value: FormEditorStateValue<"copyFeedback">) => stateController?.update({ key: "copyFeedback", value });
  const setName = (value: FormEditorStateValue<"name">) => stateController?.update({ key: "name", value });
  const setSlug = (value: FormEditorStateValue<"slug">) => stateController?.update({ key: "slug", value });
  const setFields = (value: FormEditorStateValue<"fields">) => stateController?.update({ key: "fields", value });
  // No UI edits this (owner ask 2026-09-22 removed the notify checkbox/recipients input from the
  // Fields tab — a future outside mail integration will design its own way to set it). Seeded from
  // the loaded form and carried through unchanged on every save, so an operator saving a form never
  // wipes out a `notify` setting that predates this UI removal. Lives in the section controller, not a
  // `const`, only so `handleSave`'s existing-form branch can resync it from the write's own response
  // exactly like `form`/`name`/`slug`/`fields` already do below.
  // Roving-tabindex focus targets for the tab strip below, indexed the same as `FORM_TABS` — see
  // `nextTabIndex`'s doc comment for why the index math itself lives outside the component.
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);

  const discovery = useFetchQuery({ key: ["forms", "providers"], fetch: async () => {
    if (!port.listFormProviders) throw new Error("Form provider settings are unavailable.");
    return { data: await port.listFormProviders({}) };
  } });
  const list = useFetchQuery({ key: KEYS.form(props.formId), fetch: () => port.getFormDefinition({ id: props.formId }).then(form => ({ data: formView({ form }) })) }, { enabled: !isNew });

  // Seeds `form`/`name`/`slug`/`fields`/`notify` from `list.data` exactly once per `formId` — see
  // this file's own header for the regression this guards against (a background refetch of the SAME
  // formId must not clobber in-progress edits).
  const seededFormIdRef = useRef<string | null>(null);
  const seededControllerRef = useRef<typeof stateController>(null);
  useEffect(() => {
    if (seededControllerRef.current !== stateController) { seededControllerRef.current = stateController; seededFormIdRef.current = null; }
    if (seededFormIdRef.current !== props.formId) seededFormIdRef.current = null;
    if (!stateController) return;
    if (isNew || list.status === "loading" || !list.data) return;
    if (seededFormIdRef.current === props.formId) return;
    seededFormIdRef.current = props.formId;

    const loaded = list.data.data;
    stateController.seed({ form: loaded });
  }, [props.formId, isNew, list.status, list.data, stateController]);

  // None of these invalidate `KEYS.form(props.formId)` — only `KEYS.list`. `handleSave`/
  // `handleStatusToggle` below already set `form` (and, for save, the rest of the seeded fields)
  // directly from each mutation's own response, so invalidating this hook's OWN read key would only
  // buy a redundant background refetch of data already in hand — the same reasoning
  // `use-collection-entry-editor.hooks.ts`'s `save()`/`toggleLifecycle()` document for why THEIR
  // `invalidates` names only the sibling `KEYS.entries(...)`, never their own `KEYS.entry(...)`.
  const updateMutation = useFetchMutation({
    run: ({ input }: { input: { name: string; fields: AdminFormField[]; notify: AdminFormNotify; provider?: AdminFormProviderSelection; mode?: "builder" | "html"; html?: string | undefined } }) =>
      // Targets the loaded record's real id, never `props.formId` directly — the admin URL now
      // carries the form's slug when one resolves (ui-fixes-backlog.md #8), so `props.formId` may
      // itself BE that slug. `form.id` is always the real id regardless of which one the URL held,
      // which is what lets the PUT route stay id-only (no matching slug support needed — see
      // `get-by-id.ts`'s own comment on why only the GET route resolves either). The `?? props
      // .formId` fallback only matters if this ever fired before `form` loaded, which it can't:
      // `FormEditor.tsx`'s `!isNew && !form` guards keep the whole editor (Save button included)
      // off-screen until `form` is set.
      port.updateFormDefinition({ id: form?.id ?? props.formId }, input),
  }, {
    invalidates: [KEYS.list],
  });
  const createMutation = useFetchMutation({
    run: ({ input }: { input: { name: string; slug: string; fields: AdminFormField[]; notify: AdminFormNotify; provider?: AdminFormProviderSelection; mode?: "builder" | "html"; html?: string | undefined } }) =>
      port.createFormDefinition({ name: input.name, slug: input.slug, fields: input.fields, ...(input.provider ? { provider: input.provider } : {}), ...(input.mode ? { mode: input.mode, html: input.html } : {}) }, { notify: input.notify }),
  }, {
    invalidates: [KEYS.list],
  });
  const statusMutation = useFetchMutation({
    run: ({ input }: { input: { id: string; status: "active" | "disabled" } }) => port.updateFormDefinition({ id: input.id }, { status: input.status }),
  }, {
    invalidates: [KEYS.list],
  });

  function onModeChange(next: "builder" | "html") {
    stateController?.changeMode({ mode: next }, { submitLabel: t("Send") });
  }

  async function copyEmbed() {
    if (!form) return;
    try {
      await (clipboard ?? navigator.clipboard).writeText(formHtmlEmbed({ slug: form.slug }));
      setCopyFeedback(t("Copied!"));
    } catch { setCopyFeedback(t("Could not copy embed")); }
  }

  async function handleSave() {
    // Ordinary Builder saves keep their existing endpoint/permissions. A mode change is explicit.
    const authoring = { ...authoringPatch({ mode, html, savedMode: form?.mode }), ...(provider.id !== "builtin" || form?.provider ? { provider } : {}) };
    try {
      if (isNew) {
        // `notify` here is always this hook's own blank default — a new form has no earlier value
        // to carry through, and there is no UI on this screen to set one instead.
        const created = await createMutation.mutate({ input: { name, slug, fields, notify, ...authoring } });
        // Slug, not id — see this hook's own file header / `get-by-id.ts` for the id-or-slug
        // resolution this now lands on (ui-fixes-backlog.md #8).
        navigate(`/forms/${created.slug}`);
      } else {
        // `notify` is the value this hook seeded from the loaded form and has never changed since —
        // sent back unchanged so saving name/slug/field edits can never wipe a stored notify setting
        // (see this hook's own `notify` state comment).
        // Set directly from the write's own response — `updateMutation` doesn't invalidate this
        // hook's own `KEYS.form(id)` read (see the mutations' own comment above), so there is no
        // background refetch to wait for or to accidentally clobber an in-progress edit with.
        // Mirrors `use-collection-entry-editor.hooks.ts`'s `save()`.
        const updatedCore = await updateMutation.mutate({ input: { name, fields, notify, ...authoring } });
        const updated = formView({ form: updatedCore });
        stateController?.seed({ form: updated });
      }
    } catch {
      // already surfaced through updateMutation.error/createMutation.error -> error below
    }
  }

  async function handleStatusToggle() {
    if (!form) return;
    try {
      const updatedCore = await statusMutation.mutate({ input: {
        id: form.id,
        status: form.status === "active" ? "disabled" : "active",
      } });
      setForm(formView({ form: updatedCore }));
    } catch {
      // already surfaced through statusMutation.error -> error below
    }
  }

  // Same guard as the post and widget editors (reload/close prompt included); the in-app Back
  // gets the admin's confirm modal rather than `confirmLeave`'s `window.confirm`.
  const { isDirty } = useDirtyGuard({ current: formEditorDraft({ name, slug, fields, mode, html, provider }), original: formEditorBaseline({ form, isNew }) });
  const [leaveConfirmOpen, setLeaveConfirmOpen] = useState(false);
  const leave = {
    confirmOpen: leaveConfirmOpen,
    onBack(event: { preventDefault: () => void }) {
      event.preventDefault();
      if (!isDirty) { navigate("/forms"); return; }
      setLeaveConfirmOpen(true);
    },
    confirm() {
      setLeaveConfirmOpen(false);
      navigate("/forms");
    },
    cancel: () => setLeaveConfirmOpen(false),
  };

  const saving = updateMutation.status === "pending" || createMutation.status === "pending" || statusMutation.status === "pending";
  const error = visibleFormEditorError({
    updateError: updateMutation.error,
    createError: createMutation.error,
    statusError: statusMutation.error,
    listError: list.error,
    hasForm: form !== null,
    saveFallback: t("save failed"),
    statusUpdateFallback: t("status update failed"),
    loadFormFallback: t("failed to load form"),
  });

  // Navigates to `/forms/:formId` or `/forms/:formId/submissions` (ADR-063) — `panels.tsx`'s
  // `forms` panel keys `FormEditor` off `ctx.params.formId` on BOTH routes, so this is a route
  // change, not a remount: in-progress Fields edits survive a trip to Submissions and back.
  function onTabChange(nextTab: "fields" | "submissions") {
    navigate(nextTab === "submissions" ? `/forms/${props.formId}/submissions` : `/forms/${props.formId}`);
  }

  function onTabsKeyDown(e: React.KeyboardEvent) {
    const currentIndex = FORM_TABS.findIndex((t) => t.id === tab);
    const index = nextTabIndex({ key: e.key, currentIndex });
    if (index === null) return;
    e.preventDefault();
    onTabChange(FORM_TABS[index]!.id);
    tabRefs.current[index]?.focus();
  }

  return {
    isNew,
    form, provider, setProvider,
    providers: discovery.data?.data,
    providersError: discovery.error ? `${t("Could not load form providers")}: ${describeApiError({ e: discovery.error, fallback: t("The settings service did not respond. Try opening this editor again.") })}` : null,
    mode, onModeChange, html, setHtml, copyEmbed, copyFeedback,
    answerColumns: formAnswerColumns({ fields: form?.fields ?? [] }, { yes: t("Yes"), no: t("No") }),
    name,
    setName,
    slug,
    setSlug,
    fields,
    setFields,
    tab,
    onTabChange,
    error,
    saving,
    existingFieldIds: existingFieldIdsOf({ form }),
    showTabs: !isNew && form !== null,
    tabRefs,
    onTabsKeyDown,
    handleSave,
    handleStatusToggle,
    leave,
    t,
  };
}

/**
 * Binds the real `/api/.../forms` client, `lib/router`'s `navigate`, and a `FORMS_DICT`-bound
 * translator — see `adapters/http.ts`.
 *
 * The zero-argument-deps half of the `useX(dependencies)` / `useWiredX()` pair, so
 * `FormEditor.tsx` composes this and a test composes {@link useFormEditor} with
 * `the memory adapter`, a fake `navigate`, and a fake `t`.
 */
type FormEditorStateValue<K extends keyof FormEditorState> = FormEditorState[K] | ((current: FormEditorState[K]) => FormEditorState[K]);

export function useWiredFormEditor(props: { formId: string; tab: "fields" | "submissions" }, _optional = {}): FormEditorController {
  const { formsApi, formsNavigation } = useFormsPorts();
  const { t, clipboard, adminBase } = useFormsOptions();
  const navigate = (routePath: string) => {
    if (!formsNavigation) throw new Error('Missing forms navigation port');
    formsNavigation.navigate({ base: adminBase, routePath });
  };
  return useFormEditor({ ...props, port: formsApi, navigate, t }, clipboard ? { clipboard } : {});
}

import { ConfirmDialog } from '../../../react/components/ConfirmDialog/ConfirmDialog.js';
import { DataTable } from '../../../react/components/DataTable.js';
import { RowMenu } from '../../../react/components/RowMenu/RowMenu.js';
import { agentHandle } from '@jini-ai/agentic';
import { useWiredFormsList } from '../hooks/use-forms-list.hooks.js';
import { useFormsListView } from '../hooks/forms-view.hooks.js';
/**
 * @file Forms list screen (SPEC-010 ui.spec.md §2.1/§3.1) — the `/admin/forms` route.
 * Mirrors `Menus.tsx`/`Posts.tsx`'s fetch/loading/error/table convention. Layout now follows the
 * Posts/Media page-primitive pass (`.page`/`.page-header`/`.card`/`.table-scroll`/`.empty-state`,
 * see `styles.css`) instead of the bare `.editor-header` this screen used before — see
 * `FormEditor.tsx`'s file comment for the fuller rationale (both screens were audited together).
 *
 * Row actions: `Posts.tsx`/`Pages.tsx`'s `RowMenu` pattern, INCLUDING a Delete item (T7a,
 * 2026-09-21) — `api.ts`'s generic `trash` route (`POST /trash/items`, `type: "form"`) now covers
 * forms, so there is a server capability to wire. Reached through `RowMenu`'s "Delete" ->
 * `ConfirmDialog` ("Move to trash?") -> `useFormsList`'s `removeForm`, the same three-step gate
 * `Posts.tsx`/`Pages.tsx` already use for their own row deletes; see `use-forms-list.hooks.ts`'s own
 * doc for why a click alone can never delete. What ALSO exists (unchanged by this pass) is
 * `api.updateForm`'s `status` patch, the exact call `FormEditor.tsx`'s own Disable/Enable button
 * already makes — surfaced here too so an operator doesn't have to open the editor just to toggle
 * it. That action stays un-confirmed: `FormEditor.tsx` treats it as reversible either direction (no
 * confirm step there either), so this list doesn't invent a heavier gate the editor itself doesn't
 * have. `.btn-warning`'s tone applies only going active -> disabled, same asymmetry as
 * `FormEditor.tsx`'s "Re-enabling is the safe direction" comment.
 *
 * ## Markup only
 *
 * State, the load effect, and the `api.*` calls live in `hooks/use-forms-list.hooks.ts`. That hook
 * was written during the hooks extraction but never wired — this component kept a byte-identical
 * inline copy of the same logic, so the hook was dead code and this screen was never actually
 * markup-only. Wired here; the duplicate is gone. The two copies had NOT drifted, so this is a
 * pure de-duplication with no behaviour change.
 */
export interface FormsListProps {
  /**
   * Dependency injection seam for tests — see `RedirectsProps.useRedirectsHook` for the
   * convention. Defaulted to the real hook, so `panels.tsx` passes nothing.
   */
  useFormsListHook?: typeof useWiredFormsList;
}

export function FormsList({ useFormsListHook = useWiredFormsList }: FormsListProps = {}, _optional: Record<string, never> = {}) {
  const { forms, formatFormDates, error, rowSavingId, toggleStatus, pendingDelete, setPendingDelete, removeForm, t } = useFormsListHook();

  const { rows, cancelDelete, headerActions } = useFormsListView({ forms, t, formatFormDates, toggleStatus, setPendingDelete });

  if (error && !forms) return <div className="notice error">{error}</div>;
  if (!forms) return <div className="notice">{t("Loading forms…")}</div>;

  // Form ids are stable and unique, so they disambiguate one row's edit link from another's —
  // same reasoning as every other list on this workstream. Each row's "Actions" menu (Edit/Disable/
  // Enable via `RowMenu`) shares this same per-row base (`${form.rowHandle}-menu`) now that
  // `RowMenu` (`@jini-ai/admin/react`) accepts an `agentHandle` prop — before this session it
  // published none, so its trigger and dropdown items were invisible to `page.find_elements`
  // regardless of what this file did. The Disable/Enable action also stays reachable another way:
  // `FormEditor.tsx`'s own status toggle (`form-editor-status-toggle`) does the identical
  // `api.updateForm({ status })` call.
  return (
    <div className="page">
      <div
        className="page-header"
        {...agentHandle({ handle: "forms-header" }, { role: "region", label: "Forms list header — page title and the New form button" })}
      >
        <div className="page-header-text">
          <p className="page-kicker">{t("Content")}</p>
          <h1 className="page-title">{t("Forms")}</h1>
          <p className="page-description">{t("Manage the forms embedded across the site and their submissions.")}</p>
        </div>
        <div className="page-actions">
          {headerActions}
          {/* Plain `<a className="btn-primary">`, not a `<button>` nested inside an `<a>` (invalid
              HTML, undefined activation behaviour) — same `a.btn-*` mechanism `Dashboard.tsx`'s
              "View site ↗" already uses. */}
          <a
            className="btn-primary"
            href="/admin/forms/new"
            {...agentHandle({ handle: "forms-new" }, { role: "link", label: "Create a new form" })}
          >
            {t("New form")}
          </a>
        </div>
      </div>
      {error ? <div className="notice error">{error}</div> : null}
      <DataTable<(typeof rows)[number]>
        rows={rows}
        rowKey={(form) => form.id}
        empty={
          <div className="card">
            <div className="empty-state">
              <p>{t("No forms yet.")}</p>
              <p className="page-description">{t("Create your first form to start collecting submissions.")}</p>
            </div>
          </div>
        }
        columns={[
          {
            key: "name",
            header: t("Name"),
            cell: (form, index) => (
              <a
                href={`/admin/forms/${form.slug}`}
                {...agentHandle({ handle: `${form.rowHandle}-edit` }, {
                  role: "link",
                  label: "Open this form's editor",
                })}
              >
                {form.name}
              </a>
            ),
          },
          { key: "slug", header: t("Slug"), cell: (form) => form.slug },
          {
            key: "dates",
            header: t("Created / Updated"),
            // One `<time>` per line (created, then updated — or one line when never edited). The
            // visible text is the bare short date; the event word lives in the hover title and the
            // screen-reader text only, since the header already names both events.
            cell: (form) => (
              <span className="forms-dates">
                {form.dates.map((line) => (
                  <time key={line.kind} className="forms-dates-line" dateTime={line.dateTime} title={line.label}>
                    <span aria-hidden="true">{line.text}</span>
                    <span className="visually-hidden">{line.label}</span>
                  </time>
                ))}
              </span>
            ),
          },
          { key: "fields", header: t("Fields"), cell: (form) => form.fields.length },
          {
            key: "actions",
            header: t("More"),
            cell: (form, index) => (
              <RowMenu
                triggerLabel={form.menuLabel}
                agentHandle={`${form.rowHandle}-menu`}
                items={form.menuItems}
              />
            ),
          },
        ]}
      />
      <ConfirmDialog
        open={pendingDelete !== null}
        agentHandle="forms-delete"
        title={t("Move to trash?")}
        body={
          pendingDelete ? (
            <p>
              {t("Move")} &quot;{pendingDelete.name}&quot; {t("to trash? It will disappear from the site and from this list.")}
            </p>
          ) : null
        }
        confirmLabel={t("Move to trash")}
        destructive
        pending={pendingDelete !== null && rowSavingId === pendingDelete.id}
        onConfirm={removeForm}
        onCancel={cancelDelete}
      />
    </div>
  );
}

export default FormsList;

import { MediaDialog } from './MediaDialog.js';
