import { useEffect, useMemo, useRef, useState, type KeyboardEvent, type RefObject } from 'react';

/**
 * @file `RowMenu`'s open/close state, viewport-aware positioning, and keyboard/focus behavior,
 * split out of the component so it can be swapped for a fake via the `useRowMenu` prop on
 * `RowMenuProps` — see that prop's doc comment in `RowMenu.tsx`.
 */

interface Position {
  top: number;
  left: number;
  placement: 'below' | 'above';
}

/** 8px clearance kept between the menu and the viewport edge on every side it's tested against. */
const VIEWPORT_MARGIN = 8;

type RowMenuWindow = Pick<Window, 'innerHeight' | 'innerWidth' | 'addEventListener' | 'removeEventListener'>;
type RowMenuDocument = Pick<Document, 'addEventListener' | 'removeEventListener'>;

/** What `useRowMenu` hands `RowMenu` — and the shape an injected `useRowMenu` fake must return. */
export interface RowMenuState {
  readonly open: boolean;
  readonly position: Position | null;
  readonly triggerRef: RefObject<HTMLButtonElement | null>;
  /** A callback ref from the real hook (see {@link trackOpenMenu}; `null` while closed), or a host
   *  hook's ref object. Spelled out rather than React's `Ref`, whose callback form carries a brand
   *  that fails to match across two installed `@types/react` copies (Jini's vs a host app's). */
  readonly menuRef: RefObject<HTMLDivElement | null> | ((menu: HTMLDivElement | null) => void) | null;
  readonly itemRefs: RefObject<Array<HTMLButtonElement | null>>;
  readonly onTriggerClick: () => void;
  readonly onTriggerKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  readonly onMenuKeyDown: (event: KeyboardEvent<HTMLDivElement>) => void;
  readonly selectItem: (item: { readonly onSelect: () => void }) => void;
}

/**
 * Starts the listeners one open menu needs and returns the matching stop. Called from the menu's
 * callback ref, so both elements are in hand: `trigger` is the button the menu opened from and
 * `menu` is the just-attached popup — neither is ever null here.
 *
 * Positioning runs immediately, at ref-attach time in the commit, i.e. after the (initially
 * off-screen, `visibility: hidden`) menu has actually laid out, so its real dimensions are known
 * before deciding above-vs-below — a plain `useEffect` would run one paint too late and produce a
 * visible jump. Recomputed on scroll and resize too: a portaled menu is a DOM sibling of its anchor,
 * not a child, so it does not track the anchor's position on its own the way an in-flow popup would.
 *
 * Click-outside and Escape close. Escape is document-scoped so it also works after focus
 * moves away from the popup. Scoped to the open window only, same lifecycle discipline as
 * `ConfirmButton`'s armed-only document listeners — a closed, idle `RowMenu` costs nothing beyond
 * its trigger button even with many mounted per table.
 *
 * @complexity O(1) per call and per scroll/resize/mousedown event.
 */
function trackOpenMenu(
  { trigger, menu }: { readonly trigger: HTMLElement; readonly menu: HTMLElement },
  { window, document, onPosition, onDismiss, onEscape }: {
    readonly window: RowMenuWindow;
    readonly document: RowMenuDocument;
    readonly onPosition: (position: Position) => void;
    readonly onDismiss: () => void;
    readonly onEscape: () => void;
  },
): () => void {
  function reposition() {
    const rect = trigger.getBoundingClientRect();
    const menuHeight = menu.offsetHeight;
    const menuWidth = menu.offsetWidth;
    const spaceBelow = window.innerHeight - rect.bottom;
    const fitsBelow = spaceBelow >= menuHeight + VIEWPORT_MARGIN;
    const placement: Position['placement'] =
      fitsBelow || rect.top < menuHeight + VIEWPORT_MARGIN ? 'below' : 'above';
    // Right-aligned to the trigger by default (the trigger is the table's last column), clamped
    // so it never overflows the viewport's left or right edge.
    const left = Math.min(
      Math.max(VIEWPORT_MARGIN, rect.right - menuWidth),
      window.innerWidth - menuWidth - VIEWPORT_MARGIN,
    );
    onPosition({
      top: placement === 'below' ? rect.bottom + 4 : rect.top - 4,
      left,
      placement,
    });
  }
  function onDocMouseDown(e: globalThis.MouseEvent) {
    const target = e.target as Node;
    if (menu.contains(target) || trigger.contains(target)) return;
    onDismiss();
  }
  function onDocKeyDown(e: globalThis.KeyboardEvent) {
    if (e.key !== 'Escape' || e.defaultPrevented) return;
    e.preventDefault();
    e.stopPropagation();
    onEscape();
  }
  reposition();
  window.addEventListener('scroll', reposition, true);
  window.addEventListener('resize', reposition);
  document.addEventListener('mousedown', onDocMouseDown);
  document.addEventListener('keydown', onDocKeyDown);
  return () => {
    window.removeEventListener('scroll', reposition, true);
    window.removeEventListener('resize', reposition);
    document.removeEventListener('mousedown', onDocMouseDown);
    document.removeEventListener('keydown', onDocKeyDown);
  };
}

/**
 * Owns `RowMenu`'s open/close state, positioning, and keyboard/focus behavior.
 *
 * @param itemCount Length of the caller's item list — the only piece of `RowMenuProps` this state
 *   needs, for `ArrowUp`-to-last-item and wraparound navigation.
 */
export function useRowMenu(
  { itemCount, window, document }: { readonly itemCount: number; readonly window: RowMenuWindow; readonly document: RowMenuDocument },
): RowMenuState {
  // The trigger the menu is open against; `null` while closed. Held as state (not just a boolean)
  // so the menu's callback ref below is built with the element already in hand. Read from
  // `triggerRef` at open time: an unattached trigger leaves this `null`, so a menu with nothing to
  // anchor to never opens.
  const [anchor, setAnchor] = useState<HTMLButtonElement | null>(null);
  const open = anchor !== null;
  const [position, setPosition] = useState<Position | null>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const itemRefs = useRef<Array<HTMLButtonElement | null>>([]);
  itemRefs.current = itemRefs.current.slice(0, itemCount);

  function close(returnFocus: boolean) {
    setAnchor(null);
    setPosition(null);
    if (returnFocus) triggerRef.current?.focus();
  }

  function openAt(index: number) {
    setActiveIndex(index);
    setAnchor(triggerRef.current);
  }

  // Only the open menu renders this ref, so it only exists once there is an anchor. React calls it
  // with the menu element on attach and `null` on detach (React 18 and 19 alike; attach always comes
  // first, so `stop` is set by then). A new anchor or new `window`/`document` ports make a new ref,
  // which React detaches and re-attaches — the same re-subscribe an effect's deps would give.
  const menuRef = useMemo(() => {
    if (!anchor) return null;
    let stop: () => void;
    return (menu: HTMLDivElement | null) => {
      if (menu) stop = trackOpenMenu({ trigger: anchor, menu }, { window, document, onPosition: setPosition, onDismiss: () => close(false), onEscape: () => close(true) });
      else stop();
    };
    // `close` only touches state setters and `triggerRef`, all stable across renders.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [anchor, window, document]);

  // Keeps real DOM focus on the active item (roving focus via `tabIndex={-1}` on every item except
  // the active one) rather than only tracking `activeIndex` in state — arrow-key navigation needs
  // to move the browser's actual focus for a screen reader to announce it. Waits for the first
  // position: until then the menu is `visibility: hidden`, and a browser ignores focus on that.
  const visible = open && position !== null;
  useEffect(() => {
    if (!visible) return;
    itemRefs.current[activeIndex]?.focus();
  }, [visible, activeIndex]);

  function onTriggerClick() {
    if (open) close(false);
    else openAt(0);
  }

  function onTriggerKeyDown(e: KeyboardEvent<HTMLButtonElement>) {
    if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
    e.preventDefault();
    openAt(e.key === 'ArrowDown' ? 0 : itemCount - 1);
  }

  function onMenuKeyDown(e: KeyboardEvent<HTMLDivElement>) {
    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setActiveIndex((i) => (i + 1) % itemCount);
        break;
      case 'ArrowUp':
        e.preventDefault();
        setActiveIndex((i) => (i - 1 + itemCount) % itemCount);
        break;
      case 'Home':
        e.preventDefault();
        setActiveIndex(0);
        break;
      case 'End':
        e.preventDefault();
        setActiveIndex(itemCount - 1);
        break;
      case 'Escape':
        e.preventDefault();
        e.stopPropagation();
        close(true);
        break;
      case 'Tab':
        // Leaving via Tab closes the menu but does not steal focus back to the trigger — the
        // browser's own tab order continues from wherever it lands, matching native menu behavior
        // (and unlike Escape, which is an explicit "back out" gesture).
        close(false);
        break;
      default:
        break;
    }
  }

  /** Closes (returning focus to the trigger, same as Escape) and then fires the selected item's own
   *  callback — takes the callback directly rather than a whole `RowMenuItem` so this hook stays
   *  free of any dependency on that component-level type. */
  function selectItem({ onSelect }: { readonly onSelect: () => void }) {
    close(true);
    onSelect();
  }

  return {
    open,
    position,
    triggerRef,
    menuRef,
    itemRefs,
    onTriggerClick,
    onTriggerKeyDown,
    onMenuKeyDown,
    selectItem,
  };
}

import { agentHandle } from '@jini-ai/agentic';
import type { RedirectsTranslate as Translate } from '../../models.js';
import { useWiredImportRedirectsForm } from '../hooks/wired.hooks.js';
export interface ImportRedirectsFormProps {
  /** Bound translator, threaded down from `Redirects`'s own hook rather than resolved here — see
   *  this file's header. */
  t: Translate;
  /** Raw resolved locale — needed alongside `t` because the host may resolve locale-specific message fragments. See this file's header. */
  locale: string;
  /** Dependency injection seam for tests — see `PostsProps.usePostsHook` for the convention. */
  useImportRedirectsFormHook?: typeof useWiredImportRedirectsForm;
}

/** Bulk-import affordance (REQ-04) — paste a JSON array of rule objects, submit through
 * `api.importRedirects`, and surface the `207` per-item created/failed breakdown directly
 * (never collapsed into a single pass/fail toast — a partial-batch failure is the route's own
 * designed behavior, not an edge case). */
export function ImportRedirectsForm({ t, locale, useImportRedirectsFormHook = useWiredImportRedirectsForm }: ImportRedirectsFormProps) {
  const { raw, error, result, importing, submit, changeRaw, rulesLabel, resultSummary, createdText, failedLabel } = useImportRedirectsFormHook({ t, locale });

  return (
    <details className="notice redirects-import form-measure">
      <summary>{t("Bulk import")}</summary>
      <form onSubmit={submit}>
        <label htmlFor="redirects-import-json">
          {rulesLabel}
        </label>
        <textarea
          id="redirects-import-json"
          rows={6}
          value={raw}
          onChange={changeRaw}
          placeholder='[{"matchType":"exact","fromPattern":"/old","toTarget":"/new","statusCode":301}]'
          {...agentHandle({ handle: "redirects-import-json" }, { role: "field", label: "JSON array of redirect rules to bulk-import" })}
        />
        {/* Secondary, not primary — "Add redirect" above is this screen's one actual create
            action; bulk import is a power-user path to the same result, not a second headline CTA
            competing with it. */}
        <button
          type="submit"
          className="btn-secondary"
          disabled={importing}
          {...agentHandle({ handle: "redirects-import-submit" }, { role: "button", label: "Import the pasted redirect rules" })}
        >
          {importing ? t("Importing…") : t("Import")}
        </button>
      </form>
      {error ? (
        <div className="notice error" role="alert">
          {error}
        </div>
      ) : null}
      {result ? (
        <div className="redirects-import-result">
          <p>{resultSummary}</p>
          {result.created.length > 0 ? (
            <ul>
              {result.created.map((r) => (
                <li key={r.id}>
                  <span className="save-ok">{createdText}</span> {r.fromPattern} → {r.toTarget}
                </li>
              ))}
            </ul>
          ) : null}
          {result.failed.length > 0 ? (
            <ul>
              {result.failed.map((f) => (
                <li key={f.index}>
                  <span className="save-error">{failedLabel(f)}</span>: {f.message}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}
    </details>
  );
}

import { agentHandle } from "@jini-ai/agentic";
import { Dialog } from "@jini-ai/ui-kit/react";
import { formatTimestamp } from "@jini-ai/ui/panel-kit";



import { useSeoCopy, useSeoOptions } from "../hooks/SeoPorts.hooks.js";
import { actionLabel } from "../../rules.js";
import { useWiredSitemapModal, type SitemapModalController } from "../hooks/use-sitemap-modal.hooks.js";
import { useSitemapModalRegenerate, useSitemapPresentation, useSitemapTable, useSitemapViewToggle } from "../hooks/SitemapModal.hooks.js";


/**
 * `SitemapModal` — "View sitemap" (owner request, `react/pages/SeoPage.tsx`'s Sitemap card). Reads the exact same
 * `GET /sitemap.xml` bytes a crawler gets (`sitemap-dependencies.hooks.ts`'s `defaultSitemapPort`,
 * via `siteUrl()`) and renders them as a filterable `URL | Last modified` table, with a Raw XML
 * toggle for verifying the literal response text. `changefreq`/`priority` columns were considered
 * and dropped: `server/inbound/public-http/routes/site/sitemap.ts` never emits either field (read
 * directly, not guessed), so a column for them would only ever show blank.
 *
 * Jini's Dialog owns modality and focus confinement: aria-modal promises the background cannot
 * be reached with Tab. `.sitemap-modal` widens the shared chrome to about 900px; its body is the
 * single scrolling region between fixed header and footer.
 *
 * Domain state (fetch, parse, filter, view toggle) lives in `hooks/use-sitemap-modal
 * .hooks.ts`; this file is markup only. The outer `useSeo()` mutation owns regeneration and
 * cache invalidation; `react/hooks/SitemapModal.hooks.ts` forwards that action without another read.
 *
 * ## Agent handles
 * Every interactive element carries its own `agentHandle` (grep `agentHandle(` in `react/pages/SeoPage.tsx` for
 * the convention this follows): the raw-XML link, the table/raw toggle, the filter box, each row's
 * URL link (namespaced via `buildAgentListHandles`, the same per-item scheme `MediaPickerDialog
 * .tsx` uses), the footer Regenerate button, and the footer Close button.
 */

export interface SitemapModalProps {
  locale: string;
  /** `settings.sitemapEnabled` from `useSeo()` — when `false`, the modal shows why instead of a
   *  table (REQ 8: "disabled" and "on but zero URLs" are different facts, so this never fetches to
   *  find out — it already knows).
   *
   *  Threaded into `useSitemapModal` as `SitemapModalInputs.enabled` so the fetch, header and Raw XML
   *  toggle all agree with the disabled body. */
  sitemapEnabled: boolean;
  /** `saving` from `useSeo()` — shared with the outer page's own Save/Regenerate buttons, same as
   *  today's single-flag convention (`react/pages/SeoPage.tsx`'s existing `disabled={saving}` on both). */
  regenerating: boolean;
  /** `regenerateSitemap` from `useSeo()`. Its mutation invalidates the sitemap cache on
   * success; a caught failure returns `false` and leaves the viewed XML alone. */
  onRegenerate: () => Promise<boolean>;
  onClose: () => void;
  /** Injectable seam for the modal's fetch/parse/filter/view state. Defaults to the real
   *  {@link useWiredSitemapModal}; a test can pass a fake here to exercise this component's
   *  rendering against a fixed `SitemapModalController`. */
  useModal?: typeof useWiredSitemapModal;
}

/** The header's raw-XML link + table/raw toggle — only shown once there is a real response to
 *  point at (REQ 3/6). Its own component purely so {@link SitemapModal} stays a flat sequence of
 *  blocks.
 *
 * @complexity O(1). */
function SitemapModalHeaderActions({ locale, modal }: { locale: string; modal: SitemapModalController }) {
  const { sourceUrl } = useSitemapPresentation({ locale, modal });
  const { toggleView } = useSitemapViewToggle({ modal });
  const t = useSeoCopy();
  return (
    <div className="sitemap-modal-header-actions">
      <a
        className="sitemap-modal-source-link"
        href={sourceUrl}
        target="_blank"
        rel="noreferrer"
        {...agentHandle({ handle: "seo-sitemap-open-raw-link" }, {
          role: "link",
          label: "Open the real sitemap.xml file in a new tab",
        })}
      >
        {t({ locale: locale, key: "sitemap.xml ↗" })}
      </a>
      {modal.status === "ready" ? (
        <button
          type="button"
          className="btn-secondary"
          aria-pressed={modal.view === "raw"}
          onClick={toggleView}
          {...agentHandle({ handle: "seo-sitemap-raw-toggle" }, {
            role: "button",
            label: "Toggle between the parsed table and the raw XML response",
          })}
        >
          {modal.view === "raw" ? t({ locale: locale, key: "Table" }) : t({ locale: locale, key: "Raw XML" })}
        </button>
      ) : null}
    </div>
  );
}

/** The parsed-table view: filter box + `URL | Last modified` table, or the empty-filter/empty-
 *  sitemap notices in place of a table with nothing to show. Its own component for the same
 *  flat-sequence-of-blocks reason as {@link SitemapModalHeaderActions}.
 *
 * @complexity O(1) to render — `entries`/`filteredEntries` are already computed by
 *   `useSitemapModal` (memoized there), this only maps them to JSX. */
function SitemapModalTable({ locale, modal }: { locale: string; modal: SitemapModalController }) {
  const t = useSeoCopy();
  const { formatDate = formatTimestamp } = useSeoOptions();
  const { rowHandles } = useSitemapTable({ modal });
  if (modal.entries.length === 0) return <div className="notice">{t({ locale: locale, key: "The sitemap has no URLs yet." })}</div>;



  return (
    <>
      <input
        type="search"
        className="sitemap-modal-filter"
        aria-label={t({ locale: locale, key: "Filter sitemap URLs" })}
        placeholder={t({ locale: locale, key: "Filter by URL…" })}
        value={modal.filter}
        onChange={(e) => modal.setFilter(e.target.value)}
        {...agentHandle({ handle: "seo-sitemap-filter" }, {
          role: "field",
          label: "Narrow the sitemap table by a substring match on the URL",
        })}
      />
      {modal.filteredEntries.length === 0 ? (
        <p className="muted-cell">{t({ locale: locale, key: "No URLs match this filter." })}</p>
      ) : (
        <div className="table-scroll">
          <table className="list-table">
            <thead>
              <tr>
                <th>{t({ locale: locale, key: "URL" })}</th>
                <th>{t({ locale: locale, key: "Last modified" })}</th>
              </tr>
            </thead>
            <tbody>
              {modal.filteredEntries.map((entry, index) => (
                <tr key={entry.loc}>
                  <td>
                    <a
                      href={entry.loc}
                      target="_blank"
                      rel="noreferrer"
                      {...agentHandle({ handle: rowHandles[index]! }, { role: "link", label: "Open this URL on the live site" })}
                    >
                      {entry.loc}
                    </a>
                  </td>
                  <td>{entry.lastmod === null ? <span className="muted-cell">{t({ locale: locale, key: "—" })}</span> : formatDate({ iso: entry.lastmod })}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </>
  );
}

/** The body's content-status switch (REQ 8/9: disabled, loading, error, then raw-vs-table) — kept
 *  as its own flat sequence of guards rather than a nested ternary inline in {@link SitemapModal}.
 *
 * @complexity O(1) — delegates the actual list rendering to {@link SitemapModalTable}. */
function SitemapModalBody({
  locale,
  sitemapEnabled,
  modal,
}: {
  locale: string;
  sitemapEnabled: boolean;
  modal: SitemapModalController;
}) {
  const t = useSeoCopy();
  if (!sitemapEnabled) {
    return (
      <div className="notice">
        {t({ locale: locale, key: 'Sitemap is off. Turn on "Sitemap enabled" above to publish one.' })}
      </div>
    );
  }
  if (modal.status === "loading") return <div className="notice">{t({ locale: locale, key: "Loading sitemap…" })}</div>;
  if (modal.status === "error") {
    return (
      <div className="notice error" role="alert">
        {modal.error}
      </div>
    );
  }
  if (modal.view === "raw") return <pre className="sitemap-modal-raw">{modal.xmlText}</pre>;
  return <SitemapModalTable locale={locale} modal={modal} />;
}

export function SitemapModal({
  locale,
  sitemapEnabled,
  regenerating,
  onRegenerate,
  onClose,
  useModal = useWiredSitemapModal,
}: SitemapModalProps, _optional: Record<string, never> = {}) {
  const t = useSeoCopy();
  const modal = useModal({ enabled: sitemapEnabled, onClose });
  const { title } = useSitemapPresentation({ locale, modal });
  const { handleRegenerate } = useSitemapModalRegenerate({ onRegenerate });
  // Native modality keeps Tab from reaching the background, as MediaPickerDialog now does too.

  return (
    <Dialog open title={title} onClose={() => onClose()}
      className="settings-dialog jini-domain-dialog sitemap-modal">
        <div className="sitemap-modal-header">
          <SitemapModalHeaderActions locale={locale} modal={modal} />
        </div>

        <div className="sitemap-modal-body">
          <SitemapModalBody locale={locale} sitemapEnabled={sitemapEnabled} modal={modal} />
        </div>

        <div className="widget-picker-footer">
          <span className="editor-actions">
            <button
              type="button"
              className="btn-secondary"
              onClick={handleRegenerate}
              disabled={regenerating}
              {...agentHandle({ handle: "seo-sitemap-modal-regenerate" }, {
                role: "button",
                label: "Rebuild the cached sitemap and refresh this view",
              })}
            >
              {actionLabel({ pending: regenerating, pendingLabel: t({ locale: locale, key: "Working…" }), idleLabel: t({ locale: locale, key: "Regenerate sitemap" }) })}
            </button>
            <button
              type="button"
              className="btn-secondary"
              onClick={onClose}
              data-jini-autofocus=""
              {...agentHandle({ handle: "seo-sitemap-modal-close" }, { role: "button", label: "Close the sitemap viewer" })}
            >
              {t({ locale: locale, key: "Close" })}
            </button>
          </span>
        </div>
    </Dialog>
  );
}

