                <button
                  className="tb-btn"
                  onClick={() => moveAt(i, -1)}
                  title={t("Move up")}
                  aria-label={t("Move up")}
                  {...agentHandle({ handle: `${placementHandles[i]}-move-up` }, { role: "button", label: `Move "${placement.widgetTitle}" up` })}
                >
                  ↑
                </button>
                <button
                  className="tb-btn"
                  onClick={() => moveAt(i, 1)}
                  title={t("Move down")}
                  aria-label={t("Move down")}
                  {...agentHandle({ handle: `${placementHandles[i]}-move-down` }, { role: "button", label: `Move "${placement.widgetTitle}" down` })}
                >
                  ↓
                </button>
                <button
                  className="tb-btn"
                  onClick={() => removeAt(placement.placementId)}
                  title={t("Remove")}
                  aria-label={t("Remove")}
                  {...agentHandle({ handle: `${placementHandles[i]}-remove` }, { role: "button", label: `Remove "${placement.widgetTitle}" from this region` })}
                >
                  ✕
                </button>
              </div>
            </div>
          ))
        )}
        <WidgetAddControl
          triggerLabel={t("+ Add widget")}
          onResolved={(widgetInstanceId) => addPlacement(widgetInstanceId)}
          agentHandle="widget-region-add"
        />
      </div>
    </div>
  );
}

export default WidgetRegionEditor;

import { useWidgetRegionsView } from '../hooks/page-views.hooks.js';
import { useWidgetsOptions } from '../hooks/WidgetsPorts.hooks.js';
import { DataTable } from "../../../react/components/DataTable.js";
import { agentHandle } from "@jini-ai/agentic";
import { useWiredWidgetRegions } from "../hooks/use-widget-regions.hooks.js";

/**
 * @file `WidgetRegionsScreen` (`ui.spec.md` §2.4/§3.6/§4.5/§9) — `/admin/widgets/regions` — markup
 * only. Lists currently-bound regions; the bind-new-region control is a free-text `regionKey`
 * input, mirroring `Menus.tsx`'s location-assign control exactly (no "theme declares regions" list
 * API exists to source a dropdown from — `ThemeManifest.regions` is read server-side at render
 * time, not exposed as an admin-listable registry; see `ui.spec.md` §9's disclosed dependency-gap
 * note).
 *
 * State, the fetch, and bind live in `../hooks/use-widget-regions.hooks.ts`.
 */
export interface WidgetRegionsProps {
  /**
   * Dependency injection seam for tests — the same convention `Posts.tsx`'s `usePostsHook` uses.
   * Defaulted to the real hook, so production callers pass nothing and behave exactly as before.
   */
  useWidgetRegionsHook?: typeof useWiredWidgetRegions | undefined;
}

export function WidgetRegions({ useWidgetRegionsHook = useWiredWidgetRegions }: WidgetRegionsProps = {}) {
  const { headerActions } = useWidgetsOptions();
  const { regions, error, newRegionKey, setNewRegionKey, binding, bind, t, rowHandleByKey } = useWidgetRegionsView({ useWidgetRegionsHook });

  if (error && !regions) return <div className="notice error">{error}</div>;
  if (!regions) return <div className="notice">{t("Loading regions…")}</div>;

  return (
    <div className="page">
      {/* `page-header-split` (`styles.css`) — same shared idiom every editor with a back button
          now uses: back link alone at the left rail, title block centred. This screen's own
          right-rail action isn't a Save button but the bind-a-region control (input + Bind
          button); `.page-header-actions` treats it exactly the same way (owner, 2026-09-22 — the
          back link used to float above the header entirely, uncoordinated with the title, and
          read "← Widgets"; it now reads the shared "← Back" every other editor got in the same
          pass). */}
      <div
        className="page-header page-header-split"
        {...agentHandle({ handle: "widget-regions-header" }, {
          role: "region",
          label: "Widget Regions header — the back link, the screen's title, and the bind-a-region control",
        })}
      >
        <div className="page-header-lead">
          {/* Visible label shortened to a plain "← Back" (owner, 2026-09-22 — every editor's back
              button reads the same short way now). `aria-label` keeps "Back: Widgets" —
              colon-joined rather than concatenated into a sentence so it needs no new per-locale
              phrase key and still starts with the exact visible text (WCAG 2.5.3 Label in Name). */}
          <a
            className="btn-secondary"
            href="/admin/widgets"
            aria-label={`${t("Back")}: ${t("Widgets")}`}
            {...agentHandle({ handle: "widget-regions-back" }, { role: "link", label: "Back to Widgets" })}
          >
            ← {t("Back")}
          </a>
        </div>
        <div className="page-header-text">
          <p className="page-kicker">{t("Content")}</p>
          <h1 className="page-title">{t("Widget Regions")}</h1>
          <p className="page-description">
            {t(
              'A region is a theme-declared placement area (e.g. "header", "footer", "sidebar"). Bind a region by its key to start placing widgets in it.',
            )}
          </p>
        </div>
        <div className="page-header-actions page-actions">
          {headerActions}
          {/* One group, so a wrapping row keeps the key field beside its own Bind button instead
              of beside Publish (mobile sweep 2026-10-07). */}
          <div className="widget-regions-bind">
            <input
              value={newRegionKey}
              onChange={(e) => setNewRegionKey(e.target.value)}
              placeholder="e.g. footer"
              {...agentHandle({ handle: "widget-regions-new-key" }, { role: "field", label: "New region key to bind, e.g. footer" })}
            />
            <button
              onClick={bind}
              disabled={binding || !newRegionKey.trim()}
              {...agentHandle({ handle: "widget-regions-bind" }, { role: "button", label: "Bind this region key" })}
            >
              {binding ? t("Binding…") : t("Bind region")}
            </button>
          </div>
        </div>
      </div>
      {error ? <div className="notice error">{error}</div> : null}
      <DataTable
        rows={regions}
        rowKey={(region) => region.regionKey}
        empty={
          <div className="card">
            <div className="empty-state">
              <p>{t("No regions bound yet.")}</p>
            </div>
          </div>
        }
        columns={[
          {
            key: "region-key",
            header: t("Region key"),
            cell: (region) => (
              <a
                href={`/admin/widgets/regions/${region.regionKey}`}
                {...agentHandle({ handle: `${rowHandleByKey.get(region.regionKey)}-key` }, { role: "link", label: `Manage the "${region.regionKey}" region` })}
              >
                {region.regionKey}
              </a>
            ),
          },
          { key: "placements", header: t("Placements"), cell: (region) => region.placementCount },
          {
            key: "manage",
            cell: (region) => (
              <a
                className="btn-primary"
                href={`/admin/widgets/regions/${region.regionKey}`}
                {...agentHandle({ handle: `${rowHandleByKey.get(region.regionKey)}-manage` }, { role: "link", label: `Manage the "${region.regionKey}" region` })}
              >
                {t("Manage")}
              </a>
            ),
          },
        ]}
      />
    </div>
  );
}

export default WidgetRegions;

import { useWidgetsLibraryView } from '../hooks/page-views.hooks.js';
import { useWidgetsOptions } from '../hooks/WidgetsPorts.hooks.js';
import { type AdminWidgetType } from "../../models.js";

import { ConfirmDialog } from "../../../react/components/ConfirmDialog/ConfirmDialog.js";
import { DataTable } from "../../../react/components/DataTable.js";
import { agentHandle } from "@jini-ai/agentic";
import { widgetTypeLabel } from "../../rules.js";
import { useWiredWidgetsLibrary } from "../hooks/use-widgets-library.hooks.js";

/**
 * @file `WidgetsLibraryScreen` (`ui.spec.md` §2.1/§3.1/§4.1) — the widget library/list screen,
 * `/admin/widgets` — markup only. Mirrors `Menus.tsx`'s list-table/status-badge/header-action
 * shape exactly.
 *
 * State and the fetch live in `../hooks/use-widgets-library.hooks.ts`; the shared type-label
 * derivation lives in `../../rules.ts`. Delete always confirms first (`pendingTrash`/`ConfirmDialog`
 * below) and moves the widget to the Trash — there is no purge/force-purge escalation here any
 * more (2026-09-21, `trash-delete-architecture.md`): the server's widget purge route was removed,
 * a trashed widget is hidden from this list by the server, and the Trash screen owns
 * restore/purge from here.
 */
export interface WidgetsLibraryProps {
  /**
   * Dependency injection seam for tests — the same convention `Posts.tsx`'s `usePostsHook` uses.
   * Defaulted to the real hook, so production callers pass nothing and behave exactly as before.
   */
  useWidgetsLibraryHook?: typeof useWiredWidgetsLibrary | undefined;
}

export { WidgetsLibraryNotices } from '../components/WidgetsLibraryNotices.js';
import { WidgetsLibraryNotices } from '../components/WidgetsLibraryNotices.js';

export function WidgetsLibrary({ useWidgetsLibraryHook = useWiredWidgetsLibrary }: WidgetsLibraryProps = {}) {
  const { widgetTypes, headerActions, statusLabel } = useWidgetsOptions();
  const {
    widgets,
    error,
    skippedCount,
    skippedIds,
    createType,
    setCreateType,
    pendingTrash,
    trashing,
    requestTrash,
    confirmTrash,
    cancelTrash,
    t,
    rowHandleById,
  } = useWidgetsLibraryView({ useWidgetsLibraryHook });

  if (error && !widgets) return <div className="notice error">{error}</div>;
  if (!widgets) return <div className="notice">{t("Loading widgets…")}</div>;

  return (
    <div className="page">
      <div className="page-header">
        <div className="page-header-text">
          <p className="page-kicker">{t("Content")}</p>
          <h1 className="page-title">{t("Widgets")}</h1>
          <p className="page-description">
            {t("Create reusable content blocks and place them into your theme's widget regions.")}
          </p>
        </div>
        <div className="page-actions">
          {headerActions}
          <a
            href="/admin/widgets/regions"
            {...agentHandle({ handle: "widgets-regions-link" }, { role: "link", label: "Go to Widget Regions" })}
          >
            {t("Regions →")}
          </a>
          <select
            value={createType}
            onChange={(e) => setCreateType(e.target.value as AdminWidgetType)}
            aria-label={t("Widget type to create")}
            {...agentHandle({ handle: "widgets-create-type" }, { role: "field", label: "Widget type to create" })}
          >
            {widgetTypes.map((o) => (
              <option key={o.value} value={o.value}>
                {widgetTypeLabel({ widgetType: o.value, types: widgetTypes }, { t })}
              </option>
            ))}
          </select>
          <a
            className="btn-primary"
            href={`/admin/widgets/new?type=${createType}`}
            {...agentHandle({ handle: "widgets-add-new" }, { role: "link", label: "Create a new widget of the selected type" })}
          >
            {t("Add New")}
          </a>
        </div>
      </div>
      <WidgetsLibraryNotices error={error} skippedCount={skippedCount} skippedIds={skippedIds} t={t} />
      <DataTable
        rows={widgets}
        rowKey={(widget) => widget.id}
        empty={
          <div className="card">
            <div className="empty-state">
              <p>{t("No widgets yet.")}</p>
              <p className="page-description">{t("Create one above to get started.")}</p>
            </div>
          </div>
        }
        columns={[
          {
            key: "title",
            header: t("Title"),
            cell: (widget) => (
              <a
                // Slug, not id (2026-09-22, URL-uses-slug — mirrors `FormsList.tsx`'s
                // `/admin/forms/${form.slug}` row link): the editor resolves either
                // (`read-service.ts`'s `getWidgetInstance`), but the slug is the readable one.
                href={`/admin/widgets/${widget.slug}`}
                {...agentHandle({ handle: `${rowHandleById.get(widget.id)}-edit` }, { role: "link", label: `Edit the "${widget.title}" widget` })}
              >
                {widget.title}
              </a>
            ),
          },
          {
            key: "type",
            header: t("Type"),
            cell: (widget) => widgetTypeLabel({ widgetType: widget.widgetType, types: widgetTypes }, { t }),
          },
          {
            key: "slug",
            header: t("Slug"),
            // Monospace like Collections' "Key" column (`Collections.tsx`) — a slug is an
            // identifier, not prose.
            cell: (widget) => <code>{widget.slug}</code>,
          },
          {
            key: "status",
            header: t("Status"),
            cell: (widget) => <span className={`status status-${widget.status}`}>{(statusLabel ?? t)(widget.status)}</span>,
          },
          {
            key: "actions",
            // Not converted to a `RowMenu` — this is the row's only action (see report: a menu
            // with one item is pure overhead over a direct button). Still labeled for
            // accessibility, matching `Roles.tsx`/`Users.tsx`'s existing pattern for an actions
            // column that isn't a bare `<th></th>`.
            headerLabel: t("Actions"),
            cell: (widget) => (
              <button
                onClick={() => requestTrash(widget)}
                {...agentHandle({ handle: `${rowHandleById.get(widget.id)}-trash` }, {
                  role: "button",
                  label: `Move "${widget.title}" to trash`,
                })}
              >
                {t("Trash")}
              </button>
            ),
          },
        ]}
      />
      <ConfirmDialog
        open={pendingTrash !== null}
        agentHandle="widgets-trash"
        title={t("Move to trash?")}
        body={pendingTrash ? <p>{t('Move "{title}" to trash?').replace("{title}", pendingTrash.title)}</p> : null}
        confirmLabel={t("Move to trash")}
        destructive
        pending={trashing}
        onConfirm={confirmTrash}
        onCancel={cancelTrash}
      />
    </div>
  );
}

export default WidgetsLibrary;
